async function api(path,options){options=options||{};var headers={"Accept":"application/json"};if(options.body){headers["Content-Type"]="application/json";}if(token){headers.Authorization="Bearer "+token;}var response=await fetch(API+path,Object.assign({},options,{headers:Object.assign(headers,options.headers||{})}));var raw=await response.text(),data={};try{data=raw?JSON.parse(raw):{};}catch(e){throw new Error("Invalid server response.");}if(response.status===401){logout(true);throw new Error(t("sessionExpired"));}if(!response.ok){var detail=data.detail||data.message||t("error");if(Array.isArray(detail)){detail=detail.map(function(x){return x.msg||String(x);}).join(", ");}throw new Error(typeof detail==="string"?detail:JSON.stringify(detail));}return data;}
