async function signIn(e){e.preventDefault();$("loginError").hidden=true;var btn=$("loginSubmit");btn.disabled=true;try{var r=await fetch(API+"/auth/login",{method:"POST",headers:{"Content-Type":"application/json","Accept":"application/json"},body:JSON.stringify({username:$("username").value.trim(),password:$("password").value})});var d=await r.json().catch(function(){return {};});if(!r.ok)throw new Error(d.detail||"Invalid credentials.");if(!d.access_token)throw new Error("Authentication token was not returned.");token=d.access_token;localStorage.setItem("admin_access_token",token);await bootstrap();}catch(err){token=null;localStorage.removeItem("admin_access_token");$("loginError").textContent=err.message;$("loginError").hidden=false;}finally{btn.disabled=false;}}
