async function loadRoles(){var data=await Promise.all([api("/rbac/roles"),api("/rbac/permissions")]);roles=data[0];permissions=data[1];$("rolesList").innerHTML=roles.map(function(r){return '<button class="role-choice '+(selectedRole===r.id?"active":"")+'" data-role="'+esc(r.id)+'"><b>'+esc(r.name)+'</b><small>'+(r.permissions||[]).length+' '+t("permissionCount")+'</small></button>';}).join("")||'<p class="muted">'+t("noRecords")+'</p>';document.querySelectorAll("[data-role]").forEach(function(b){b.addEventListener("click",function(){selectedRole=b.dataset.role;loadRoleDetail();});});if(!selectedRole&&roles.length)selectedRole=roles[0].id;loadRoleDetail();}
